package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="reprogramaciones_reserva") public class ReprogramacionReserva{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="rpr_id")private Long rprId;@Column(name="emp_id",nullable=false)private Long empId;@Column(name="res_id",nullable=false)private Long resId;@Column(name="rpr_ini_ant",nullable=false)private LocalDateTime rprIniAnt;@Column(name="rpr_fin_ant",nullable=false)private LocalDateTime rprFinAnt;@Column(name="rpr_ini_nue",nullable=false)private LocalDateTime rprIniNue;@Column(name="rpr_fin_nue",nullable=false)private LocalDateTime rprFinNue;@Column(name="rpr_mot",length=300)private String rprMot;@Column(name="rpr_usu_mov",nullable=false,length=100)private String rprUsuMov;@Column(name="rpr_fec_mov",nullable=false)private LocalDateTime rprFecMov;@Column(name="rpr_act",nullable=false)private Boolean rprAct;
 public Long getRprId(){return rprId;}public void setRprId(Long v){rprId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getResId(){return resId;}public void setResId(Long v){resId=v;}public LocalDateTime getRprIniAnt(){return rprIniAnt;}public void setRprIniAnt(LocalDateTime v){rprIniAnt=v;}public LocalDateTime getRprFinAnt(){return rprFinAnt;}public void setRprFinAnt(LocalDateTime v){rprFinAnt=v;}public LocalDateTime getRprIniNue(){return rprIniNue;}public void setRprIniNue(LocalDateTime v){rprIniNue=v;}public LocalDateTime getRprFinNue(){return rprFinNue;}public void setRprFinNue(LocalDateTime v){rprFinNue=v;}public String getRprMot(){return rprMot;}public void setRprMot(String v){rprMot=v;}public String getRprUsuMov(){return rprUsuMov;}public void setRprUsuMov(String v){rprUsuMov=v;}public LocalDateTime getRprFecMov(){return rprFecMov;}public void setRprFecMov(LocalDateTime v){rprFecMov=v;}public Boolean getRprAct(){return rprAct;}public void setRprAct(Boolean v){rprAct=v;}
}
